CREATE COLUMN TABLE "TEST_AP"."OCRN" ("CurrCode" NVARCHAR(3) NOT NULL , "CurrName" NVARCHAR(20), "ChkName" NVARCHAR(20), "Chk100Name" NVARCHAR(20), "DocCurrCod" NVARCHAR(3), "FrgnName" NVARCHAR(20), "F100Name" NVARCHAR(20), "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "RoundSys" SMALLINT CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "Decimals" SMALLINT CS_INT DEFAULT -1, "ISRCalc" NVARCHAR(1) DEFAULT 'N', "RoundPym" NVARCHAR(1) DEFAULT 'N', "ConvUnit" NVARCHAR(1) DEFAULT 'N', "BaseCurr" NVARCHAR(3), "Factor" DECIMAL(21,6) CS_FIXED, "ChkNamePl" NVARCHAR(20), "Chk100NPl" NVARCHAR(20), "FrgnNamePl" NVARCHAR(20), "F100NamePl" NVARCHAR(20), "ISOCurrCod" NVARCHAR(3), "MaxInDiff" DECIMAL(21,6) CS_FIXED, "MaxOutDiff" DECIMAL(21,6) CS_FIXED, "MaxInPcnt" DECIMAL(21,6) CS_FIXED, "MaxOutPcnt" DECIMAL(21,6) CS_FIXED, "ISOCurrNum" NVARCHAR(3), PRIMARY KEY ("CurrCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
